}

using UniversityCourseCatalog.Models;

namespace UniversityCourseCatalog.Services;

public class CatalogService
{
    private readonly List<Department> _departments;
    private readonly List<Course> _courses;
    private readonly List<EnrollmentRequest> _enrollments = new();

    public CatalogService()
    {
        _departments = new List<Department>
        {
            new() { Id = 1, Name = "Computer Science", Code = "CS", Description = "Study of computation, algorithms, and information systems." },
            new() { Id = 2, Name = "Mathematics", Code = "MATH", Description = "Study of numbers, structures, and patterns." },
            new() { Id = 3, Name = "Physics", Code = "PHYS", Description = "Study of matter, energy, and the fundamental forces of nature." },
            new() { Id = 4, Name = "English", Code = "ENG", Description = "Study of literature, writing, and language arts." },
            new() { Id = 5, Name = "History", Code = "HIST", Description = "Study of past events and human civilization." }
        };

        _courses = new List<Course>
        {
            new() { Id = 1, DepartmentId = 1, Code = "CS 101", Title = "Introduction to Programming", Description = "Learn the fundamentals of programming using Python. Topics include variables, control flow, functions, and basic data structures.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Dr. Sarah Chen", InstructorBio = "Dr. Chen has 15 years of experience teaching introductory CS courses and has published research on CS education pedagogy.", IsFeatured = true, DepartmentName = "Computer Science" },
            new() { Id = 2, DepartmentId = 1, Code = "CS 201", Title = "Data Structures and Algorithms", Description = "Study of fundamental data structures (trees, graphs, hash tables) and algorithm design techniques including divide-and-conquer and dynamic programming.", Credits = 4, Schedule = "Tue/Thu 10:30–11:45 AM", InstructorName = "Dr. James Wright", InstructorBio = "Dr. Wright specializes in algorithm optimization and has contributed to open-source algorithm libraries.", IsFeatured = true, DepartmentName = "Computer Science" },
            new() { Id = 3, DepartmentId = 1, Code = "CS 301", Title = "Database Systems", Description = "Principles of database design, SQL, normalization, transaction processing, and an introduction to NoSQL systems.", Credits = 3, Schedule = "Mon/Wed 2:00–3:15 PM", InstructorName = "Dr. Maria Lopez", InstructorBio = "Dr. Lopez worked as a database architect at a Fortune 500 company before joining academia.", IsFeatured = false, DepartmentName = "Computer Science" },
            new() { Id = 4, DepartmentId = 1, Code = "CS 401", Title = "Machine Learning", Description = "Introduction to supervised and unsupervised learning, neural networks, and practical applications of ML in industry.", Credits = 4, Schedule = "Tue/Thu 1:00–2:15 PM", InstructorName = "Dr. Alex Kumar", InstructorBio = "Dr. Kumar's research focuses on deep learning and has published over 40 papers in top AI conferences.", IsFeatured = true, DepartmentName = "Computer Science" },
            new() { Id = 5, DepartmentId = 2, Code = "MATH 101", Title = "Calculus I", Description = "Limits, derivatives, and integrals of single-variable functions with applications to science and engineering.", Credits = 4, Schedule = "Mon/Wed/Fri 10:00–10:50 AM", InstructorName = "Dr. Robert Taylor", InstructorBio = "Dr. Taylor is an award-winning educator known for making calculus accessible to all students.", IsFeatured = true, DepartmentName = "Mathematics" },
            new() { Id = 6, DepartmentId = 2, Code = "MATH 201", Title = "Linear Algebra", Description = "Vector spaces, linear transformations, matrices, determinants, eigenvalues and eigenvectors.", Credits = 3, Schedule = "Tue/Thu 9:00–10:15 AM", InstructorName = "Dr. Emily Park", InstructorBio = "Dr. Park researches applied linear algebra and its connections to data science.", IsFeatured = false, DepartmentName = "Mathematics" },
            new() { Id = 7, DepartmentId = 2, Code = "MATH 301", Title = "Probability and Statistics", Description = "Probability theory, random variables, distributions, hypothesis testing, and regression analysis.", Credits = 3, Schedule = "Mon/Wed/Fri 11:00–11:50 AM", InstructorName = "Dr. David Kim", InstructorBio = "Dr. Kim consults for biotech companies on statistical modeling and experimental design.", IsFeatured = false, DepartmentName = "Mathematics" },
            new() { Id = 8, DepartmentId = 3, Code = "PHYS 101", Title = "General Physics I", Description = "Mechanics, thermodynamics, and waves. Includes a weekly laboratory component.", Credits = 4, Schedule = "Mon/Wed/Fri 1:00–1:50 PM + Thu Lab 2:00–4:50 PM", InstructorName = "Dr. Michael Brown", InstructorBio = "Dr. Brown is an experimental physicist who has worked at CERN and Fermilab.", IsFeatured = true, DepartmentName = "Physics" },
            new() { Id = 9, DepartmentId = 3, Code = "PHYS 201", Title = "Electromagnetism", Description = "Electric and magnetic fields, Maxwell's equations, electromagnetic waves, and optics.", Credits = 4, Schedule = "Tue/Thu 11:00 AM–12:15 PM", InstructorName = "Dr. Lisa Zhang", InstructorBio = "Dr. Zhang's research involves novel electromagnetic materials and photonics.", IsFeatured = false, DepartmentName = "Physics" },
            new() { Id = 10, DepartmentId = 4, Code = "ENG 101", Title = "College Composition", Description = "Develop critical reading, thinking, and writing skills through analysis of diverse texts and essay composition.", Credits = 3, Schedule = "Mon/Wed/Fri 9:00–9:50 AM", InstructorName = "Prof. Amanda Torres", InstructorBio = "Prof. Torres is a published author and has taught writing workshops nationally.", IsFeatured = false, DepartmentName = "English" },
            new() { Id = 11, DepartmentId = 4, Code = "ENG 205", Title = "American Literature", Description = "Survey of American literary traditions from the colonial period to the present day.", Credits = 3, Schedule = "Tue/Thu 2:00–3:15 PM", InstructorName = "Dr. William Foster", InstructorBio = "Dr. Foster specializes in 20th-century American fiction and has authored three books on the subject.", IsFeatured = false, DepartmentName = "English" },
            new() { Id = 12, DepartmentId = 5, Code = "HIST 101", Title = "World Civilizations", Description = "A global survey of major civilizations and their cultural, political, and economic developments.", Credits = 3, Schedule = "Mon/Wed 3:30–4:45 PM", InstructorName = "Dr. Patricia Nguyen", InstructorBio = "Dr. Nguyen is a historian of Southeast Asia and has conducted fieldwork across the region.", IsFeatured = false, DepartmentName = "History" },
            new() { Id = 13, DepartmentId = 5, Code = "HIST 250", Title = "Modern European History", Description = "Europe from the French Revolution to the present, covering political, social, and cultural transformations.", Credits = 3, Schedule = "Tue/Thu 3:30–4:45 PM", InstructorName = "Dr. Hans Mueller", InstructorBio = "Dr. Mueller studied at the University of Heidelberg and specializes in 19th-century European nationalism.", IsFeatured = false, DepartmentName = "History" }
        };
    }

    public List<Department> GetDepartments() => _departments;

    public Department? GetDepartment(int id) => _departments.FirstOrDefault(d => d.Id == id);

    public List<Course> GetCourses(string? searchTerm = null, int? departmentId = null)
    {
        var query = _courses.AsEnumerable();

        if (departmentId.HasValue)
            query = query.Where(c => c.DepartmentId == departmentId.Value);

        if (!string.IsNullOrWhiteSpace(searchTerm))
        {
            var term = searchTerm.Trim().ToLowerInvariant();
            query = query.Where(c =>
                c.Title.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Code.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.Description.Contains(term, StringComparison.OrdinalIgnoreCase) ||
                c.InstructorName.Contains(term, StringComparison.OrdinalIgnoreCase));
        }

        return query.ToList();
    }

    public List<Course> GetFeaturedCourses() => _courses.Where(c => c.IsFeatured).ToList();

    public Course? GetCourse(int id) => _courses.FirstOrDefault(c => c.Id == id);

    public void SubmitEnrollment(EnrollmentRequest request)
    {
        _enrollments.Add(request);
    }
}

