@page "/courses/{Id:int}"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>@(_course?.Title ?? "Course Details")</PageTitle>

@if (_course is null)
{
    <h1>Course Not Found</h1>
    <p>The requested course does not exist.</p>
    <a href="/courses" class="btn btn-secondary">Back to Catalog</a>
}
else
{
    <nav aria-label="breadcrumb">
        <ol class="breadcrumb">
            <li class="breadcrumb-item"><a href="/courses">Courses</a></li>
            <li class="breadcrumb-item active">@_course.Code</li>
        </ol>
    </nav>

    <h1>@_course.Code — @_course.Title</h1>

    <div class="row mt-4">
        <div class="col-md-8">
            <h4>Description</h4>
            <p>@_course.Description</p>

            <h4 class="mt-4">Schedule</h4>
            <p><strong>@_course.Schedule</strong></p>

            <h4 class="mt-4">Credits</h4>
            <p><span class="badge bg-primary fs-6">@_course.Credits credits</span></p>
        </div>
        <div class="col-md-4">
            <div class="card">
                <div class="card-body">
                    <h5 class="card-title">Instructor</h5>
                    <h6 class="card-subtitle mb-2 text-muted">@_course.InstructorName</h6>
                    <p class="card-text">@_course.InstructorBio</p>
                </div>
            </div>

            <div class="mt-3">
                <a href="/enroll?courseId=@_course.Id" class="btn btn-success w-100">Enroll in This Course</a>
            </div>
        </div>
    </div>
}

@code {
    [Parameter] public int Id { get; set; }

    private Course? _course;

    protected override void OnInitialized()
    {
        _course = CatalogService.GetCourse(Id);
    }
}

@page "/enroll"
@using UniversityCourseCatalog.Models
@using UniversityCourseCatalog.Services
@inject CatalogService CatalogService

<PageTitle>Enrollment Request</PageTitle>

<h1>Enrollment Request</h1>
<p>Submit your enrollment request using the form below.</p>

@if (_submitted)
{
    <div class="alert alert-success">
        <h4>Request Submitted!</h4>
        <p>Your enrollment request has been submitted successfully. You will receive a confirmation via your university email.</p>
        <a href="/courses" class="btn btn-primary">Browse More Courses</a>
    </div>
}
else
{
    <div class="row">
        <div class="col-md-6">
            <form method="post" @formname="enrollment" @onsubmit="HandleSubmit">
                <AntiforgeryToken />

                <div class="mb-3">
                    <label for="studentName" class="form-label">Full Name</label>
                    <input type="text" class="form-control" id="studentName" name="StudentName"
                           @bind="_model.StudentName" required />
                </div>

                <div class="mb-3">
                    <label for="studentId" class="form-label">Student ID</label>
                    <input type="text" class="form-control" id="studentId" name="StudentId"
                           @bind="_model.StudentId" required placeholder="e.g., STU-12345" />
                </div>

                <div class="mb-3">
                    <label for="courseId" class="form-label">Course</label>
                    <select class="form-select" id="courseId" name="CourseId" @bind="_model.CourseId" required>
                        <option value="0" disabled>Select a course...</option>
                        @foreach (var course in _courses)
                        {
                            <option value="@course.Id">@course.Code — @course.Title</option>
                        }
                    </select>
                </div>

                <button type="submit" class="btn btn-primary">Submit Enrollment Request</button>
            </form>
        </div>
    </div>
}

@code {
    [SupplyParameterFromQuery] public int? CourseId { get; set; }

    [SupplyParameterFromForm] private EnrollmentRequest _model { get; set; } = new();

    private List<Course> _courses = new();
    private bool _submitted;

    protected override void OnInitialized()
    {
        _courses = CatalogService.GetCourses();
        if (CourseId.HasValue && _model.CourseId == 0)
            _model.CourseId = CourseId.Value;
    }

    private void HandleSubmit()
    {
        if (string.IsNullOrWhiteSpace(_model.StudentName) ||
            string.IsNullOrWhiteSpace(_model.StudentId) ||
            _model.CourseId == 0)
            return;

        CatalogService.SubmitEnrollment(_model);
        _submitted = true;
    }
}

